def depth_within_limit(text):
    """Preliminary nesting scan. Returns False if depth ever exceeds 64."""
    depth = 0
    in_str = False
    esc = False
    for ch in text:
        if in_str:
            if esc:
                esc = False
            elif ch == '\\':
                esc = True
            elif ch == '"':
                in_str = False
        else:
            if ch == '"':
                in_str = True
            elif ch == '{' or ch == '[':
                depth += 1
                if depth > 64:
                    return False
            elif ch == '}' or ch == ']':
                if depth > 0:
                    depth -= 1
    return True


def decode_json(text):
    def pairs_hook(pairs):
        d = {}
        for k, v in pairs:
            if k in d:
                raise WireError('E_JSON')
            d[k] = v
        return d

