    def parse_float(s):
        return float(s)

    try:
        return json.loads(text, object_pairs_hook=pairs_hook,
                          parse_constant=parse_const, parse_float=parse_float)
    except WireError:
        raise
    except Exception:
        raise WireError('E_JSON')


def has_surrogate(s):
    for ch in s:
        o = ord(ch)
        if 0xD800 <= o <= 0xDFFF:
            return True
    return False


def check_unicode(obj):
    stack = [obj]
    while stack:
        x = stack.pop()
        if isinstance(x, str):
            if has_surrogate(x):
                raise WireError('E_SCHEMA')
        elif isinstance(x, dict):
            for k, v in x.items():
                stack.append(k)
                stack.append(v)
        elif isinstance(x, list):
            stack.extend(x)


